        trialBalance: "Data comes from real virtual/real account postings (assets/mock/accounts.mock.js, ACCOUNT_TRANSACTIONS) — the same ones that drive balances in Accounting → Chart of Accounts: the opening balance is computed from postings before the period, turnover from postings inside the period, closing = opening + net turnover. Group accounts aren't included (their balance is the sum of children, see the account card in Chart of Accounts). Balance sheet, P&L and cash flow from the backend catalogue (see the comment in financial-reports.js) aren't implemented yet — that's the next step.",
