/**
 * t('nav.clients') -> строка на текущем currentLang (глобальная переменная в app.js).
 * Падает обратно на 'ru', если ключа нет в выбранном языке (защита от пустых строк).
 */
function t(path) {
  const lookup = (dict) => path.split(".").reduce((acc, key) => (acc ? acc[key] : undefined), dict);
  return lookup(I18N[currentLang]) ?? lookup(I18N.ru) ?? path;
}


































